window.OL_I18N = {"lang":"el","dict":{"meta.appName":"Έλεγχος συμβατότητας eSIM Openline","meta.searchTitle":"Συμβατότητα {q} με eSIM · Openline","ui.skip":"Μετάβαση στο περιεχόμενο","ui.brandAria":"Openline — Ελέγξτε αν η συσκευή σας είναι συμβατή","ui.brandSub":"Ελέγξτε αν η συσκευή σας είναι συμβατή","lang.label":"Γλώσσα","lang.aria":"Αλλαγή γλώσσας","hero.titleHtml":"Υποστηρίζει η συσκευή σας <span class=\"accent\">eSIM</span>;","hero.tag":"Κινητό, tablet, smartwatch, hotspot — πληκτρολογήστε οποιαδήποτε μάρκα ή μοντέλο και θα σας πούμε αμέσως αν μπορεί να γίνει ενεργοποίηση του Openline.","search.placeholder":"Δοκιμάστε «iPhone 18 Pro», «Galaxy Z Fold8», «Pixel Watch 5», «iPad Air» ή έναν κωδικό μοντέλου…","search.aria":"Αναζητήστε μάρκα, μοντέλο ή κωδικό μοντέλου συσκευής","search.clear":"Καθαρισμός αναζήτησης","stats.devices":"συσκευές","stats.compatible":"συμβατές","stats.notCompatible":"μη συμβατές","stats.brands":"μάρκες","filters.label":"Φίλτρα","filters.summaryAll":"Όλες οι συσκευές · Όλες οι μάρκες","filters.explain":"Επιλέξτε κατάσταση συμβατότητας ή/και μία ή περισσότερες μάρκες. Τα φίλτρα συνδυάζονται με το πλαίσιο αναζήτησης και η λίστα παρακάτω ενημερώνεται άμεσα.","filters.compat":"Συμβατότητα","filters.compatAria":"Φίλτρα συμβατότητας","filters.brands":"Μάρκες","filters.brandsAria":"Φίλτρα μάρκας","filters.clearAll":"Εκκαθάριση όλων","filters.compatOnly":"Μόνο συμβατές","filters.notCompatOnly":"Μόνο μη συμβατές","filters.allStatuses":"Όλες οι καταστάσεις","filters.nBrands":{"one":"{n} μάρκα","other":"{n} μάρκες"},"filters.matchHtml":{"one":"<strong>{n}</strong> συσκευή ταιριάζει","other":"<strong>{n}</strong> συσκευές ταιριάζουν"},"cat.count":{"one":"{n} συσκευή","other":"{n} συσκευές"},"results.all":"Όλες οι συσκευές","results.matching":"Συσκευές που ταιριάζουν","results.ofTotalHtml":"<strong>{n}</strong> από {total}","results.totalHtml":"<strong>{n}</strong> συνολικά","results.showingFirst":" · εμφάνιση των πρώτων {max}","legend.ok":"Υποστηρίζει eSIM","legend.err":"Μόνο φυσική κάρτα SIM","status.ok":"Συμβατή","status.no":"Μη συμβατή","status.okAria":"Συμβατή με eSIM","status.noAria":"Μη συμβατή με eSIM","note.caveatAria":"Περιφερειακή εξαίρεση: {note}","popover.aria":"Περιφερειακή εξαίρεση","popover.close":"Κλείσιμο","empty.noMatchTitle":"Δεν βρέθηκε ακριβές αποτέλεσμα.","empty.noMatchBodyHtml":"Δοκιμάστε μόνο τη μάρκα (π.χ. <em>Samsung</em>) ή τον ακριβή κωδικό μοντέλου (π.χ. <em>SM-S921B</em>). Αν η συσκευή σας κυκλοφόρησε μετά το 2021 εκτός ηπειρωτικής Κίνας, είναι πολύ πιθανό να υποστηρίζει eSIM.","empty.bothTitle":"Καμία συσκευή δεν ταιριάζει με την αναζήτηση και τα φίλτρα σας.","empty.bothBodyHtml":{"one":"Η αναζήτησή σας για <em>{q}</em> επιστρέφει συνολικά <strong>{n}</strong> συσκευή, αλλά δεν ταιριάζει με τα φίλτρα που έχετε επιλέξει. Μήπως τα φίλτρα προκαλούν τη σύγκρουση;","other":"Η αναζήτησή σας για <em>{q}</em> επιστρέφει συνολικά <strong>{n}</strong> συσκευές, αλλά καμία δεν ταιριάζει με τα φίλτρα που έχετε επιλέξει. Μήπως τα φίλτρα προκαλούν τη σύγκρουση;"},"empty.filtersTitle":"Καμία συσκευή δεν ταιριάζει με τα φίλτρα σας.","empty.filtersBody":"Δοκιμάστε να χαλαρώσετε τα φίλτρα — ο συνδυασμός σπάνιων καταστάσεων συμβατότητας με λίγες μάρκες μπορεί να μην αφήσει κανένα αποτέλεσμα.","empty.nothing":"Δεν υπάρχει τίποτα εδώ ακόμα.","empty.resetFilters":"Επαναφορά φίλτρων","empty.clearSearch":"Καθαρισμός αναζήτησης","footer.privacy":"Απόρρητο","footer.terms":"Όροι","footer.socialAria":"Η Openline στα μέσα κοινωνικής δικτύωσης","footer.onNetwork":"Η Openline στο {network}","footer.handleOnNetwork":"@askopenline στο {network}","footer.indexedHtml":"<b id=\"footer-total\">{n}</b> συσκευές στη βάση δεδομένων","region.US":"Ηνωμένες Πολιτείες","region.HK":"Χονγκ Κονγκ","region.CN":"ηπειρωτική Κίνα","region.KR":"Νότια Κορέα","region.JP":"Ιαπωνία","region.AU":"Αυστραλία","region.TW":"Ταϊβάν","region.SEA":"Νοτιοανατολική Ασία","region.EU":"Ευρωπαϊκή Ένωση","region.IN":"Ινδία","region.UK":"Ηνωμένο Βασίλειο","exp.carrierWatch":"Τα smartwatch με cellular αποκτούν eSIM μέσω προγράμματος παρόχου για ρολόγια, που ρυθμίζεται από την εφαρμογή συνοδού του συζευγμένου κινητού (εφαρμογή Apple Watch, Galaxy Wearable, εφαρμογή Pixel Watch). Οι κωδικοί QR eSIM κινητού ή ταξιδιού δεν μπορούν να εγκατασταθούν απευθείας στο ρολόι, οπότε βεβαιωθείτε ότι ο πάροχός σας προσφέρει πρόγραμμα για αυτό το ρολόι.","exp.gpsOnly":"Αυτή είναι η έκδοση μόνο με GPS. Δεν διαθέτει πομποδέκτη κινητής τηλεφωνίας, επομένως δεν μπορεί να χρησιμοποιήσει eSIM. Η έκδοση GPS + Cellular του ίδιου ρολογιού έχει διαφορετικό κωδικό μοντέλου.","exp.cnHkMoDualNano":"Τα iPhone αυτής της γενιάς που πωλούνται στην ηπειρωτική Κίνα, το Χονγκ Κονγκ και το Μακάο διαθέτουν δύο υποδοχές φυσικής nano-SIM και δεν έχουν eSIM. Το Openline δεν μπορεί να εγκατασταθεί σε αυτές τις συσκευές. Ελέγξτε τον κωδικό μοντέλου στις Ρυθμίσεις › Γενικά › Πληροφορίες.","exp.cnDualNano":"Η έκδοση αυτού του κινητού για την ηπειρωτική Κίνα χρησιμοποιεί δύο φυσικές κάρτες nano-SIM και δεν έχει eSIM. Τα μοντέλα που πωλούνται οπουδήποτε αλλού υποστηρίζουν eSIM. Ελέγξτε τον κωδικό μοντέλου στις Ρυθμίσεις › Γενικά › Πληροφορίες.","exp.cnLocalRules":"Η έκδοση για την ηπειρωτική Κίνα υποστηρίζει eSIM, αλλά οι κινεζικοί πάροχοι ενεργοποιούν eSIM μόνο στα καταστήματά τους με έλεγχο ταυτότητας και τα προφίλ eSIM του εξωτερικού δεν μπορούν να εγκατασταθούν όσο βρίσκεστε στην ηπειρωτική Κίνα. Εκτός Κίνας, οι ταξιδιωτικές eSIM όπως η Openline εγκαθίστανται κανονικά.","exp.esimOnlyUsJpCaGulf":"Οι συσκευές που πωλούνται στις ΗΠΑ, τον Καναδά, την Ιαπωνία, το Μεξικό και τις χώρες του Κόλπου δεν έχουν υποδοχή SIM και λειτουργούν μόνο με eSIM. Αλλού το κινητό διαθέτει και υποδοχή nano-SIM, ενώ οι συσκευές για την ηπειρωτική Κίνα ίσως δεν έχουν eSIM. Το Openline λειτουργεί σε κάθε έκδοση με δυνατότητα eSIM.","exp.noSimTray":"Αυτή η έκδοση δεν έχει φυσική υποδοχή SIM: κάθε γραμμή, συμπεριλαμβανομένου του Openline, προστίθεται ως eSIM. Μπορείτε να αποθηκεύσετε πολλές eSIM και να εναλλάσσεστε μεταξύ τους από τις Ρυθμίσεις.","exp.iden":"Αυτή η συσκευή λειτουργεί στο δίκτυο iDEN της Motorola (Nextel / Boost push-to-talk), το οποίο καταργήθηκε πλήρως από τη Sprint τον Ιούνιο του 2013. Δεν μπορεί να συνδεθεί σε κανένα σύγχρονο δίκτυο κινητής τηλεφωνίας — με eSIM ή χωρίς. Μόνο ως αντικείμενο μουσείου/συλλογής.","exp.cdmaVerizon":"Πρόκειται για συσκευή αποκλειστικά CDMA, κατασκευασμένη για το παλαιό δίκτυο 2G/3G CDMA της Verizon, το οποίο τερματίστηκε στις 31 Δεκεμβρίου 2022. Δεν έχει καθόλου υποδοχή SIM (φυσική ή eSIM) — το CDMA ταυτοποιείται στο δίκτυο μέσω του ESN/MEID της συσκευής και όχι μέσω SIM. Δεν μπορεί να χρησιμοποιηθεί με το Openline ή με κανέναν σύγχρονο πάροχο.","exp.cdmaSprint":"Πρόκειται για συσκευή CDMA, κατασκευασμένη για το παλαιό δίκτυο της Sprint, το οποίο η T-Mobile τερμάτισε οριστικά στις 31 Μαΐου 2022. Τα νεότερα μοντέλα Sprint πρόσθεσαν LTE/GSM, αλλά τα παλαιότερα είναι αποκλειστικά CDMA και δεν μπορούν να συνδεθούν σε κανένα σύγχρονο δίκτυο — με ή χωρίς eSIM.","exp.sunset":"Αυτή η συσκευή βασίζεται σε δίκτυα 3G ή παλαιότερα δίκτυα 4G που οι πάροχοι έχουν τερματίσει (AT&T 3G τον Φεβρουάριο του 2022, T-Mobile τον Φεβρουάριο του 2022, Verizon τον Δεκέμβριο του 2022, τα περισσότερα ευρωπαϊκά 3G έως το 2025). Ακόμη κι αν έχει λειτουργική υποδοχή SIM, στις περισσότερες χώρες δεν υπάρχει δίκτυο για να συνδεθεί.","exp.windowsPhone":"Αυτή η συσκευή τρέχει Windows Phone (ή Windows 10 Mobile), το οποίο η Microsoft διέκοψε το 2019 — το Store, οι ενημερώσεις ασφαλείας και οι περισσότερες υπηρεσίες της έχουν πάψει να λειτουργούν. Δεν διαθέτει υλικό eSIM και σχεδόν καθόλου υποστήριξη σύγχρονων εφαρμογών. Ακατάλληλη για καθημερινή χρήση.","exp.kaios":"Πρόκειται για κινητό με πλήκτρα (feature phone) με KaiOS. Σχεδόν καμία συσκευή KaiOS δεν υποστηρίζει eSIM — χρησιμοποιούν φυσική SIM (συνήθως nano-SIM) και απευθύνονται σε αγορές οικονομικών feature phone μόνο 4G, όπως η Ινδία (JioPhone) και η Αφρική. Το Openline δεν μπορεί να εγκατασταθεί εδώ.","exp.telematics":"Πρόκειται για μονάδα τηλεματικής οχήματος (Tesla, BMW, Audi κ.λπ.) με εργοστασιακά ενσωματωμένη eSIM, κολλημένη στην πλακέτα συνδεσιμότητας του αυτοκινήτου. Η eSIM παρέχεται από τον κατασκευαστή του αυτοκινήτου στο εργοστάσιο και δεν μπορεί να αντικατασταθεί με προφίλ που εγκαθιστά ο χρήστης, όπως το Openline. Δεν επισκευάζεται από τον χρήστη.","exp.satellite":"Πρόκειται για δορυφορική συσκευή επικοινωνίας/GPS (Garmin inReach, SPOT, Zoleo, Iridium GO) που χρησιμοποιεί το δορυφορικό δίκτυο Iridium ή Globalstar — όχι δίκτυο κινητής GSM/LTE. Δεν μπορεί να χρησιμοποιήσει eSIM με τη συμβατική έννοια· η συνδεσιμότητα συνδέεται με ιδιόκτητη συνδρομή του κατασκευαστή της συσκευής.","exp.medical":"Πρόκειται για συσκευή ιατρικής ειδοποίησης ή PERS (προσωπική απόκριση έκτακτης ανάγκης). Ο πομποδέκτης κινητής της είναι κλειδωμένος στον πάροχο υπηρεσιών (Lively, Medical Guardian, Life Alert, Bay Alarm) και λειτουργεί μόνο με τη συνδρομή παρακολούθησής τους. Δεν μπορεί να εγκαταστήσει eSIM τρίτων.","exp.rugged":"Πρόκειται για συσκευή Samsung Enterprise / Rugged (σειρά Galaxy XCover) για επαγγελματίες πεδίου — αποθήκες, υγειονομική περίθαλψη, φιλοξενία. Υποστηρίζει eSIM, αλλά η ενεργοποίηση ίσως περνά από τη ρύθμιση MDM Samsung Knox του εργοδότη σας. Αν η συσκευή είναι ξεκλείδωτη, το Openline εγκαθίσταται όπως σε οποιοδήποτε κινητό.","exp.harmony":"Αυτή η συσκευή τρέχει HarmonyOS (Huawei) χωρίς Google Mobile Services. Η ενεργοποίηση eSIM συνήθως απαιτεί την εφαρμογή υπηρεσιών παρόχου του Huawei EMUI/HarmonyOS· τα προφίλ Openline εγκαθίστανται μέσω κωδικού QR, αλλά οι ενεργοποιήσεις μέσω Google Wallet δεν λειτουργούν. Οι συσκευές που πωλούνται στην ηπειρωτική Κίνα ίσως απορρίπτουν επιπλέον διεθνή προφίλ eSIM λόγω περιορισμών του κινεζικού firmware.","exp.dualEsimOnly":"Αυτή η έκδοση υποστηρίζει δύο eSIM ταυτόχρονα, αλλά δεν έχει φυσική υποδοχή SIM. Το Openline λειτουργεί — απλώς δεν μπορείτε να το συνδυάσετε με nano-SIM. Σε ορισμένες περιφερειακές εκδόσεις μπορεί να είναι ενεργή μόνο μία eSIM τη φορά.","exp.euCarrier":"Ορισμένες ευρωπαϊκές εκδόσεις αυτής της συσκευής, κλειδωμένες σε πάροχο, κυκλοφόρησαν με απενεργοποιημένη την eSIM σε επίπεδο firmware. Τα ξεκλείδωτα/παγκόσμια μοντέλα υποστηρίζουν eSIM κανονικά. Αν αποτύχει η ενεργοποίηση, επικοινωνήστε με τον αρχικό πάροχό σας.","exp.usCarrier":"Πρόκειται για έκδοση με επωνυμία αμερικανικού παρόχου (AT&T, T-Mobile, Verizon, Sprint) με κλειδωμένο firmware και συχνά υποστήριξη ζωνών ειδικά για τον πάροχο. Η eSIM μπορεί να είναι απενεργοποιημένη ή περιορισμένη στα προφίλ του παρόχου. Οι ξεκλείδωτες διεθνείς συσκευές του ίδιου μοντέλου συνήθως λειτουργούν με το Openline· οι συσκευές με επωνυμία παρόχου ίσως όχι.","exp.verizon":"Οι εκδόσεις αυτού του Pixel για τη Verizon είχαν απενεργοποιημένη την eSIM κατά την κυκλοφορία στο δίκτυο της Verizon. Οι ξεκλείδωτες συσκευές και οι συσκευές άλλων παρόχων υποστηρίζουν eSIM κανονικά.","exp.googleFi":"Σε αυτή τη γενιά Pixel, η eSIM ήταν διαθέσιμη μόνο μέσω του Google Fi στις ΗΠΑ. Οι άλλοι πάροχοι χρησιμοποιούσαν μόνο φυσική SIM. Οι παγκόσμιες ξεκλείδωτες συσκευές υποστηρίζουν eSIM παντού.","exp.usEsimOnly":"Στα iPhone αυτού του μοντέλου που αγοράστηκαν στις ΗΠΑ, η Apple αφαίρεσε εντελώς την υποδοχή φυσικής SIM — πρέπει να χρησιμοποιήσετε eSIM. Παντού αλλού, το κινητό έχει φυσική υποδοχή SIM επιπλέον της eSIM. Το Openline λειτουργεί και στις δύο περιπτώσεις.","exp.cnOnly":"Αυτή η συσκευή κυκλοφορεί με firmware για την εγχώρια αγορά της Κίνας. Η υποστήριξη eSIM υπάρχει στα χαρτιά, αλλά τα διεθνή προφίλ συχνά αποτυγχάνουν να ενεργοποιηθούν εκτός ηπειρωτικής Κίνας. Αν σκοπεύετε να ταξιδέψετε, επιβεβαιώστε την ενεργοποίηση eSIM με τον πωλητή πριν από την αγορά.","exp.jpDomestic":"Τα κινητά με επωνυμία ιαπωνικών παρόχων (NTT DoCoMo, au, SoftBank, Rakuten) είναι συνήθως κλειδωμένα στο σχέδιο συχνοτήτων της Ιαπωνίας. Το υλικό eSIM λειτουργεί στην Ιαπωνία· η ενεργοποίηση στο εξωτερικό εξαρτάται από την επικάλυψη συχνοτήτων με τα τοπικά δίκτυα.","exp.regionLocked":"Η ενεργοποίηση eSIM αυτής της συσκευής είναι κλειδωμένη ανά περιοχή σε επίπεδο firmware. Δέχεται μόνο προφίλ eSIM από παρόχους της χώρας/περιοχής όπου πωλήθηκε.","exp.krOnly":"Αυτό το μοντέλο πωλείται μόνο στη Νότια Κορέα και χρησιμοποιεί τις ζώνες των παρόχων KT/SKT/LGU+. Διαθέτει υλικό eSIM, αλλά η ενεργοποίηση στο εξωτερικό δεν είναι αξιόπιστη.","exp.foldable":"Πρόκειται για αναδιπλούμενη συσκευή — διαθέτει υποδοχή eSIM, αλλά ορισμένες αναδιπλούμενες εκδόσεις που πωλούνται στην Κίνα δεν υποστηρίζουν διεθνή eSIM. Βεβαιωθείτε ότι ο κωδικός μοντέλου αντιστοιχεί στη διεθνή έκδοση (SKU).","exp.hotspot":"Πρόκειται για φορητό Wi-Fi hotspot / router MiFi και όχι για κινητό. Δέχεται eSIM για να μοιράζεται δεδομένα κινητής με τις άλλες συσκευές σας. Το Openline παρέχεται με τον ίδιο τρόπο όπως σε κινητό.","exp.simTrayOnly":"Αυτή η συσκευή διαθέτει πομποδέκτη κινητής τηλεφωνίας, αλλά δέχεται μόνο φυσική nano-SIM ή micro-SIM — δεν έχει τσιπ eSIM. Δεν μπορείτε να εγκαταστήσετε εδώ το Openline ως eSIM· θα χρειαστείτε πρόγραμμα με φυσική SIM.","exp.wifiOnly":"Αυτή η έκδοση είναι μόνο Wi-Fi — δεν έχει μόντεμ κινητής τηλεφωνίας. Δεν μπορεί να εγκαταστήσει καμία eSIM. Αναζητήστε την έκδοση LTE / 5G / Cellular του ίδιου μοντέλου.","exp.ereader":"Πρόκειται για e-reader με εργοστασιακά ενσωματωμένο μόντεμ κινητής, συνδεδεμένο με το δωρεάν πρόγραμμα δεδομένων του κατασκευαστή (Amazon Whispernet, B&N nook κ.λπ.). Η eSIM/SIM δεν παρέχεται από τον χρήστη — δεν μπορείτε να τοποθετήσετε προφίλ Openline.","exp.cellularEsimOnly":"Αυτή η έκδοση διαθέτει σύνδεση κινητής μόνο μέσω eSIM — δεν υπάρχει φυσική υποδοχή SIM στη συσκευή. Το Openline εγκαθίσταται απευθείας μέσω κωδικού QR.","exp.unverifiedVariant":"Τα δεδομένα μας συνδέουν αυτόν τον κωδικό μοντέλου με περισσότερες από μία οικογένειες προϊόντων. Συνήθως αυτό σημαίνει ότι η Apple/Samsung/Google επαναχρησιμοποίησε έναν εσωτερικό αριθμό σε διαφορετικές γενιές ή ότι μια περιφερειακή έκδοση (SKU) μετονομάστηκε. Το Openline θα πρέπει να λειτουργεί, αλλά αν ο κωδικός μοντέλου στο κουτί δεν ταιριάζει με τη συσκευή που βλέπετε, επιβεβαιώστε με τον κατασκευαστή πριν από την αγορά.","exp.crossBrand":"Αυτός ο κωδικός μοντέλου εμφανίζεται και σε συσκευή άλλης μάρκας (Vivo/iQOO, Xiaomi/POCO, Nokia/HMD, Nubia/ZTE κ.λπ.). Συνήθως πρόκειται για αδελφή εταιρεία — το υλικό είναι συχνά πανομοιότυπο, κάποιες φορές με άλλη επωνυμία — αλλά η υποστήριξη eSIM και η πιστοποίηση παρόχων μπορεί να διαφέρουν μεταξύ των δύο μαρκών. Ελέγξτε τη συσκευασία λιανικής της δικής σας συσκευής.","exp.modelUnverified":"Δεν διαθέτουμε επίσημο κωδικό μοντέλου/εξαρτήματος για αυτή τη συσκευή — συνήθως επειδή πρόκειται για wearable, μονάδα τηλεματικής οχήματος, hotspot ή αξεσουάρ, με SKU που δεν δημοσιεύεται. Η υποστήριξη eSIM αναφέρεται στις προδιαγραφές του κατασκευαστή, αλλά το Openline δεν μπορεί να αντιστοιχίσει συγκεκριμένο κωδικό υλικού ώστε να εγγυηθεί τη συμβατότητα. Επιβεβαιώστε με τον κατασκευαστή πριν βασιστείτε σε αυτήν.","exp.ambiguous":"Το όνομα του προϊόντος εδώ είναι πολύ σύντομο («13», «F7», «M6»…) και μπορεί εύκολα να συγχέεται με μοντέλα του ίδιου αριθμού από άλλες μάρκες ή γενιές. Ελέγξτε τη μάρκα και τον κωδικό μοντέλου στη συσκευή σας για να βεβαιωθείτε ότι η καταχώριση αντιστοιχεί σε αυτήν που διαθέτετε.","exp.cnFirmware":"Αυτή η συσκευή κυκλοφορεί με firmware για την εγχώρια αγορά της Κίνας. Υπάρχει υλικό eSIM, αλλά το κινεζικό firmware συχνά μπλοκάρει την ενεργοποίηση διεθνών προφίλ eSIM. Αν σκοπεύετε να χρησιμοποιήσετε το Openline εκτός ηπειρωτικής Κίνας, επιβεβαιώστε με τον πωλητή πριν από την αγορά ότι το firmware δεν είναι κλειδωμένο ανά περιοχή.","exp.regionExcluded":"Οι συσκευές αυτού του μοντέλου που πωλούνται στις ακόλουθες περιοχές κυκλοφορούν χωρίς υλικό eSIM, επομένως λειτουργεί μόνο η φυσική υποδοχή SIM: {regions}. Παντού αλλού η eSIM υποστηρίζεται και το Openline ενεργοποιείται κανονικά. Αν αγοράσατε τη συσκευή στο εξωτερικό ή από εισαγωγέα της γκρίζας αγοράς, ελέγξτε τον κωδικό μοντέλου με τη λίστα του κατασκευαστή.","note.3G free":"Δωρεάν 3G","note.3G/4G":"3G/4G","note.AU/JP/TW excluded":"Εξαιρούνται AU/JP/TW","note.Ambiguous name":"Διφορούμενο όνομα","note.CDMA":"CDMA","note.CN firmware":"Firmware CN","note.CN/HK excluded":"Εξαιρούνται CN/HK","note.CN/HK/MO: dual nano-SIM":"CN/HK/MO: διπλή nano-SIM","note.CN/IN":"CN/IN","note.CN/IN dual-eSIM only":"CN/IN: μόνο διπλή eSIM","note.CN: dual nano-SIM":"CN: διπλή nano-SIM","note.CN: local eSIM rules":"CN: τοπικοί κανόνες eSIM","note.Carrier watch plan":"Πρόγραμμα παρόχου ρολογιού","note.Cross-brand model code":"Κωδικός κοινός σε μάρκες","note.E-reader":"E-reader","note.Enterprise rugged":"Επαγγελματικό ανθεκτικό","note.Foldable":"Αναδιπλούμενο","note.GPS only":"Μόνο GPS","note.GPS/satellite tracker":"Πομπός GPS/δορυφορικός","note.Google Fi/US only":"Μόνο Google Fi/ΗΠΑ","note.HarmonyOS":"HarmonyOS","note.JP domestic band lock":"Κλείδωμα ζωνών JP","note.KR only":"Μόνο KR","note.KR/CN":"KR/CN","note.KaiOS feature phone":"Feature phone KaiOS","note.Medical alert":"Ιατρική ειδοποίηση","note.Mobile hotspot":"Mobile hotspot","note.Model code unverified":"Ανεπιβεβαίωτος κωδικός","note.Nextel/Boost":"Nextel/Boost","note.No eSIM hardware":"Χωρίς υλικό eSIM","note.No eSIM in most regions":"Χωρίς eSIM στις περισσότερες περιοχές","note.Not on Verizon/Sprint":"Όχι σε Verizon/Sprint","note.SEA excluded":"Εξαιρείται η SEA","note.SIM tray only":"Μόνο υποδοχή SIM","note.Sprint":"Sprint","note.US carrier variant":"Έκδοση παρόχου ΗΠΑ","note.US model excluded":"Εξαιρείται μοντέλο US","note.US variant excluded":"Εξαιρείται έκδοση US","note.US/HK excluded":"Εξαιρούνται US/HK","note.US/JP: eSIM ok":"US/JP: eSIM εντάξει","note.US: eSIM only":"US: μόνο eSIM","note.Unverified variant":"Ανεπιβεβαίωτη έκδοση","note.Vehicle telematics":"Τηλεματική οχήματος","note.Verizon":"Verizon","note.Verizon US no eSIM":"Verizon US: χωρίς eSIM","note.Verizon-only 5G":"5G μόνο Verizon","note.Wi-Fi + Cellular only":"Μόνο Wi-Fi + Cellular","note.Wi-Fi + free 4G":"Wi-Fi + δωρεάν 4G","note.Wi-Fi only":"Μόνο Wi-Fi","note.Wi-Fi only in most regions":"Μόνο Wi-Fi στις περισσότερες περιοχές","note.Wi-Fi/3G":"Wi-Fi/3G","note.Windows Phone":"Windows Phone","note.deprecated":"καταργημένο","note.dual-eSIM in EU":"διπλή eSIM στην ΕΕ","note.eSIM only":"Μόνο eSIM","note.eSIM only (no SIM tray)":"Μόνο eSIM (χωρίς υποδοχή SIM)","note.eSIM only in US/JP/CA/Gulf":"Μόνο eSIM σε US/JP/CA/Κόλπο","note.eSIM only via Google Fi":"Μόνο eSIM μέσω Google Fi","note.iDEN":"iDEN","note.sunset":"τέλος δικτύου"}};
